package org.springframework.samples.petclinic.rest;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.ContentCachingResponseWrapper;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

/**
 * Makes {@code POST /api/owners} idempotent per {@code Idempotency-Key} header: a repeat
 * carrying an already-seen key replays the original create's body with status 200 instead
 * of creating a duplicate. Kept as a standalone filter so the create endpoint stays
 * untouched.
 */
@Component
public class IdempotentOwnerCreateFilter extends OncePerRequestFilter {

    private final Map<String, byte[]> responsesByKey = new ConcurrentHashMap<>();

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        String key = request.getHeader("Idempotency-Key");
        if (key == null || !"POST".equalsIgnoreCase(request.getMethod())
                || !request.getRequestURI().endsWith("/api/owners")) {
            chain.doFilter(request, response);
            return;
        }
        byte[] original = responsesByKey.get(key);
        if (original != null) {
            response.setStatus(HttpServletResponse.SC_OK);
            response.setContentType("application/json");
            response.getOutputStream().write(original);
            return;
        }
        ContentCachingResponseWrapper captured = new ContentCachingResponseWrapper(response);
        chain.doFilter(request, captured);
        if (captured.getStatus() == HttpServletResponse.SC_CREATED) {
            responsesByKey.put(key, captured.getContentAsByteArray());
        }
        captured.copyBodyToResponse();
    }
}

