package org.springframework.samples.petclinic.rest;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Set;

import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.ContentCachingResponseWrapper;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

/**
 * Guarantees every rejection response carries an RFC 7807 {@code application/problem+json}
 * body. Controllers that reject a request with a bare status and no body (e.g. a 400 for an
 * out-of-range postcode) are given a minimal problem document here, while responses that
 * already supply one (the {@code ExceptionControllerAdvice} problem details) pass through
 * untouched. Kept as a standalone filter so the rejecting endpoints stay unchanged.
 */
@Component
public class ProblemDetailErrorFilter extends OncePerRequestFilter {

    /** Rejection statuses that must always answer with a problem document. */
    private static final Set<Integer> REJECTION_STATUSES = Set.of(400, 409, 429);

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        ContentCachingResponseWrapper captured = new ContentCachingResponseWrapper(response);
        chain.doFilter(request, captured);
        if (REJECTION_STATUSES.contains(captured.getStatus()) && captured.getContentSize() == 0) {
            writeProblem(captured);
        }
        captured.copyBodyToResponse();
    }

    /** Writes a minimal {type, title, status, detail} problem document for the captured status. */
    private void writeProblem(ContentCachingResponseWrapper response) throws IOException {
        HttpStatus status = HttpStatus.valueOf(response.getStatus());
        String reason = status.getReasonPhrase();
        byte[] body = ("{\"type\":\"about:blank\",\"title\":\"" + reason + "\",\"status\":" + status.value()
            + ",\"detail\":\"" + reason + "\"}").getBytes(StandardCharsets.UTF_8);
        response.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
        response.getOutputStream().write(body);
    }
}

